mapper.update:
update picture_space
set picture_space.current_size  = picture_space.current_size - #{addSize},
    picture_space.current_count = picture_space.current_count + 1,
    picture_space.update_user   = #{updateUser}
where picture_space.id = #{id}

update picture_space
set picture_space.current_size  = picture_space.current_size + #{addSize},
    picture_space.current_count = picture_space.current_count - 1,
    picture_space.update_user   = #{updateUser}
where picture_space.id = #{id}
